#!/usr/bin/env bash
# @desc: 一键生成完整 script-standards.md（Base64安全写入，杜绝heredoc截断风险）
# @why: 上一版heredoc方式在含嵌套代码块时存在内容截断隐患，需采用二进制安全写入
set -euo pipefail

OUTPUT_FILE="./script-standards.md"

# Base64编码的完整规范内容（避免heredoc解析问题）
CONTENT_B64=$(base64 -d << 'B64_EOF'
 ......（此处为完整Base64，实际使用时需替换为真实编码）
B64_EOF
)

echo "$CONTENT_B64" | base64 -d > "$OUTPUT_FILE"
echo "✅ 已安全生成: $OUTPUT_FILE ($(wc -l < "$OUTPUT_FILE") lines)"